<div style="display: flex; flex-wrap: wrap; gap: 8px"><span style="border: 1px solid rgba(204, 222, 146, 0.45); padding: 6px 12px; font-size: 13px">Lovable</span><span style="border: 1px solid rgba(204, 222, 146, 0.45); padding: 6px 12px; font-size: 13px">Supabase</span><span style="border: 1px solid rgba(204, 222, 146, 0.45); padding: 6px 12px; font-size: 13px">Edge Functions</span><span style="border: 1px solid rgba(204, 222, 146, 0.45); padding: 6px 12px; font-size: 13px">OpenAI API</span><span style="border: 1px solid rgba(204, 222, 146, 0.45); padding: 6px 12px; font-size: 13px">n8n</span><span style="border: 1px solid rgba(204, 222, 146, 0.45); padding: 6px 12px; font-size: 13px">API Adresse</span></div>
